import 'package:hum/hum.dart';

/// A synthesised handclap modelled on the classic analog drum-machine circuit
/// (TR-808 / TR-909): bandpassed noise shaped by two summed envelope paths —
/// 4 rapid, tightly-spaced micro-bursts ("multiple hands") generated by three
/// short non-feedback delays of the trigger plus a longer diffuse tail [Decay].
///
/// ```text
/// trigger ─┬─ Decay(burstDecay) ──────────────────────┐
///          ├─ Delay(spread) ───── Decay(burstDecay) ──┤
///          ├─ Delay(spread * 2) ─ Decay(burstDecay) ──┼─ Sum
///          ├─ Delay(spread * 3) ─ Decay(burstDecay) ──┤   │
///          ├─ Decay(tailDecay) ── Mult(tailLevel) ────┘   │
///          │                                              │
///          │  NoiseGenerator ─ SvfFilter(bandpass) ───────┴─ Mult ─ Mult(velocity)
///          └─ Sah (velocity)
/// ```
///
/// The [trigger] doubles as velocity. Any positive value fires the clap, and
/// the value at the moment of the trigger scales the amplitude until the next
/// hit.
///
/// - [spread] is the spacing in seconds between successive micro-bursts
///   (`~0.010`–`0.013`s gives the classic flamming handclap texture).
/// - [burstDecay] is the decay time of each individual micro-burst.
/// - [tailDecay] and [tailLevel] control the longer diffuse room tail.
/// - [cutoff] and [resonance] tune the bandpass body (~1.1–1.5 kHz).
/// - [seed] seeds the noise generator for repeatable output.
class Clap {
  final Sah velocity;
  final NoiseGenerator noiseSource;
  final SvfFilter bandpassFilter;
  final List<Delay> burstDelays;
  final List<Decay> burstEnvs;
  final Decay tailEnv;
  final Mult tailScaled;
  final Sum envSum;
  final Mult amp;
  final Mult velocityAmp;

  Clap._({
    required this.velocity,
    required this.noiseSource,
    required this.bandpassFilter,
    required this.burstDelays,
    required this.burstEnvs,
    required this.tailEnv,
    required this.tailScaled,
    required this.envSum,
    required this.amp,
    required this.velocityAmp,
  });

  Outlet get outlet => velocityAmp.outlet;

  factory Clap({
    required Outlet trigger,
    double spread = 0.011,
    ControlParam<double> burstDecay = const .value(0.008),
    ControlParam<double> tailDecay = const .value(0.14),
    ControlParam<double> tailLevel = const .value(0.35),
    ControlParam<double> cutoff = const .value(1200.0),
    ControlParam<double> resonance = const .value(2.2),
    int? seed,
  }) {
    final velocity = Sah.mono(trigger: trigger, input: trigger, threshold: 0.0);

    final noiseSource = NoiseGenerator.white(seed: seed);
    final bandpassFilter = SvfFilter(
      input: noiseSource.outlet,
      cutoff: cutoff,
      resonance: resonance,
    );

    // 4 staggered micro-bursts: t = 0, spread, 2*spread, 3*spread.
    // Using finite non-feedback delays guarantees the burst train stops after
    // 4 snaps instead of endlessly re-triggering `Decay` (which fires on any
    // > 0 rising edge, no matter how quiet).
    final burstDelays = [
      for (int i = 1; i <= 3; i++)
        Delay.mono(
          input: trigger,
          time: .value(spread * i),
          feedback: const .value(0.0),
          mix: const .value(1.0),
          maxDelay: spread * 3 + 0.05,
          interpTime: 0.0,
        ),
    ];

    final burstEnvs = [
      Decay.pure(trigger: trigger, time: burstDecay),
      for (final d in burstDelays)
        Decay.pure(trigger: d.outlet, time: burstDecay),
    ];

    final tailEnv = Decay.pure(trigger: trigger, time: tailDecay);
    final tailScaled = Mult.mono(input: tailEnv.outlet, value: tailLevel);

    final envSum = Sum(
      inputs: [
        for (final env in burstEnvs) env.outlet,
        tailScaled.outlet,
      ],
    );

    final amp = Mult.mono(
      input: bandpassFilter.bandpass,
      value: .signal(envSum.outlet),
    );
    final velocityAmp = Mult.mono(
      input: amp.outlet,
      value: .signal(velocity.outlet),
    );

    return Clap._(
      velocity: velocity,
      noiseSource: noiseSource,
      bandpassFilter: bandpassFilter,
      burstDelays: burstDelays,
      burstEnvs: burstEnvs,
      tailEnv: tailEnv,
      tailScaled: tailScaled,
      envSum: envSum,
      amp: amp,
      velocityAmp: velocityAmp,
    );
  }
}
